R=[
(8855907,"मसूर की दाल का सूप","सऊदी शैली का मसूर का सूप प्याज़, लहसुन, मिर्च और मसालों के आधार पर कद्दू और गाजर जैसी सब्ज़ियों के साथ पकाया जाता है, फिर चिकना ब्लेंड किया जाता है; यह सर्दियों का पसंदीदा व्यंजन है। इस नुस्खे में मक्खन की जगह ऑलिव ऑयल, पानी या बिना नमक का सब्ज़ी स्टॉक, अधिक सब्ज़ियाँ और कम आलू है।","6","1 कटोरा (लगभग 350 मिलीलीटर)",
["220 ग्राम लाल मसूर की दाल, धुली और छनी हुई","4 छोटे चम्मच ऑलिव ऑयल (20 ग्राम)","1 प्याज़, कटा हुआ (120 ग्राम)","2 लहसुन की कलियाँ, कटी हुई (10 ग्राम)","2 हरी मिर्च (20 ग्राम)","½ हरी शिमला मिर्च (80 ग्राम)","250 ग्राम कद्दू, टुकड़ों में कटा हुआ","2 गाजर, टुकड़ों में कटी हुई (150 ग्राम)","1 टमाटर (150 ग्राम)","1 छोटा आलू, छिला और पोटैशियम निकाला हुआ (100 ग्राम)","1 छोटा चम्मच जीरा, 1 छोटा चम्मच बज़ार (सऊदी मसाला मिश्रण), 1 छोटा चम्मच साबुत धनिया","1.5 लीटर पानी या घर का बना बिना नमक का सब्ज़ी स्टॉक","1 छोटा चम्मच नमक (6 ग्राम)","परोसने के लिए 1 बड़ा चम्मच नींबू का रस (15 ग्राम)"],
["आलू को छोटे टुकड़ों में काटें, 2 घंटे गुनगुने पानी में भिगोएँ, फिर बहुत सारे पानी में 5 मिनट उबालें और छान लें।","प्रेशर कुकर में तेल गरम करें और लहसुन को नरम करें, फिर प्याज़, मिर्च और शिमला मिर्च डालें।","मसाले और साबुत धनिया डालें, फिर मसूर डालकर धीमी आँच पर 5 मिनट चलाएँ।","कद्दू, गाजर, टमाटर, आलू, स्टॉक और नमक डालें, कुकर बंद करें और मध्यम आँच पर 20–25 मिनट पकाएँ (या साधारण बर्तन में 40 मिनट)।","चाहें तो मिर्च निकाल दें, सूप को चिकना ब्लेंड करें और गरम पानी से गाढ़ापन ठीक करें।","ऊपर से नींबू निचोड़कर गरम परोसें।"],
["क्या बदला गया: मक्खन की जगह ऑलिव ऑयल, तैयार स्टॉक की जगह पानी या घर का बना बिना नमक का सब्ज़ी स्टॉक, और अधिक कद्दू व गाजर के साथ केवल थोड़ा पोटैशियम निकाला हुआ आलू।","किडनी के लिए सुझाव: मसूर, आलू और टमाटर पोटैशियम और फॉस्फोरस के स्रोत हैं; आलू को पहले चरण की तरह तैयार करें या उसकी जगह कद्दू लें, और एक ही कटोरा लें।","मधुमेह के लिए सुझाव: एक कटोरे में लगभग 36 ग्राम कार्बोहाइड्रेट और 6 ग्राम फाइबर होता है; इसे सलाद के साथ परोसें और रोटी कम खाएँ।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, शाकाहारी, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, सैयदाती किचन, मौज़ू3"],[]),
(8856991,"हिजाज़ी बलीला","बलीला हिजाज़ का लोकप्रिय नाश्ता है: धीमी आँच पर पकाए छोले, जिन्हें जीरे, सिरके और चुकंदर, खीरे व गाजर के झटपट अचार के साथ परोसा जाता है। इस नुस्खे में भिगोने में बेकिंग सोडा नहीं है, डिब्बाबंद की जगह ताज़ा चुकंदर, बोतल की तीखी सॉस की जगह ताज़ी मिर्च, और नमक कम है।","4","1 छोटा कटोरा (लगभग 250 ग्राम)",
["छोलों के लिए::200 ग्राम सूखे छोले, 12 घंटे भिगोए हुए","छोलों के लिए::2 तेज पत्ते और पुदीने की 2 टहनियाँ","छोलों के लिए::1 छोटा चम्मच पिसा जीरा","छोलों के लिए::⅓ छोटा चम्मच नमक (2 ग्राम)","छोलों के लिए::1 छोटा चम्मच ऑलिव ऑयल (4.5 ग्राम)","अचार वाले सलाद के लिए::1 मध्यम ताज़ा चुकंदर (150 ग्राम)","अचार वाले सलाद के लिए::1 बड़ा खीरा, टुकड़ों में कटा हुआ (150 ग्राम)","अचार वाले सलाद के लिए::1 गाजर, मोटी कद्दूकस की हुई (100 ग्राम)","अचार वाले सलाद के लिए::2 बड़े चम्मच गहरा (माल्ट जैसा) या सेब का सिरका (30 मिलीलीटर), 6 बड़े चम्मच पानी में मिलाया हुआ","अचार वाले सलाद के लिए::1 बड़ा चम्मच नींबू का रस (15 ग्राम)","अचार वाले सलाद के लिए::1 ताज़ी लाल मिर्च, बारीक कटी हुई (वैकल्पिक)"],
["छोलों को छानकर धोएँ, फिर बर्तन में तेज पत्तों और पुदीने के साथ 5 सेमी ऊपर तक पानी डालकर रखें।","उबाल आने दें और झाग हटाएँ, फिर थोड़ा (लगभग 100 मिलीलीटर) ठंडा पानी डालें और फिर झाग हटाएँ; इसे दो बार और दोहराएँ।","आँच बहुत धीमी कर दें और 2–3 घंटे पकाएँ जब तक छोले नरम पर साबुत न रहें, आख़िरी 30 मिनट में नमक डालें।","इस बीच चुकंदर को 25–30 मिनट नरम होने तक उबालें, फिर छीलकर टुकड़ों में काटें और 3 बड़े चम्मच पकाने का पानी रख लें।","चुकंदर और गाजर को पतले किए सिरके, नींबू के रस, चुकंदर के पानी और मिर्च के साथ मिलाएँ और 20 मिनट रखें; परोसने से ठीक पहले खीरा डालें।","छोलों को थोड़े शोरबे के साथ छोटे कटोरों में डालें, जीरा और ऑलिव ऑयल डालें, और ऊपर एक चम्मच सलाद रखें।"],
["क्या बदला गया: भिगोने में बेकिंग सोडा नहीं है, डिब्बाबंद की जगह ताज़ा चुकंदर, नमकीन बोतल की सॉस की जगह ताज़ी मिर्च, और थोड़ा नमक।","किडनी के लिए सुझाव: छोले और चुकंदर में पोटैशियम अधिक होता है, और छोलों में फॉस्फोरस; एक ही छोटा कटोरा लें, छोलों को उनके शोरबे से छान लें, और चुकंदर कम व खीरा अधिक ले सकते हैं।","मधुमेह के लिए सुझाव: एक कटोरे में लगभग 39 ग्राम कार्बोहाइड्रेट और 8 ग्राम फाइबर होता है और यह ब्लड शुगर को धीरे बढ़ाता है; इसे मिठाई की जगह शाम के नाश्ते में लें।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, शाकाहारी, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, मौज़ू3 सुफ़रती, जस्टफ़ूड"],[]),
(8861015,"मेमने के साथ क़ोज़ी","क़ोज़ी सऊदी अरब और खाड़ी देशों की दावत का व्यंजन है: मांस को साबुत मसालों के साथ धीमी आँच पर पकाया जाता है, ओवन में भूरा किया जाता है, और उसके शोरबे में पके चावल पर पास्ता, मेवे और उबले अंडों के साथ परोसा जाता है। इस घरेलू नुस्खे में पूरे मेमने की जगह लगभग 600 ग्राम कम वसा वाली मेमने की जाँघ, चावल और साबुत गेहूँ के पास्ता की नापी हुई मात्रा, तले की जगह भुने बादाम, और कम घी व नमक है।","4","1 प्लेट (सलाद सहित लगभग 450 ग्राम)",
["स्टॉक के लिए::600 ग्राम कम वसा वाली मेमने की जाँघ (एक टुकड़ा या बड़े टुकड़े)","स्टॉक के लिए::1 बड़ा प्याज़, चौथाई में कटा हुआ (150 ग्राम)","स्टॉक के लिए::3 लहसुन की कलियाँ (10 ग्राम)","स्टॉक के लिए::1 गाजर (100 ग्राम)","स्टॉक के लिए::1 दालचीनी की डंडी, 6 इलायची, 4 लौंग, 1 सूखा नींबू (लूमी), 2 तेज पत्ते और ½ छोटा चम्मच काली मिर्च के दाने","मांस को भूरा करने के लिए::1 बड़ा चम्मच बिना नमक वाला टमाटर पेस्ट (15 ग्राम)","मांस को भूरा करने के लिए::1 बड़ा चम्मच ऑलिव ऑयल (13.5 ग्राम)","मांस को भूरा करने के लिए::1 चुटकी केसर, 2 बड़े चम्मच गुलाबजल में भिगोया हुआ","चावल और पास्ता के लिए::170 ग्राम बासमती चावल","चावल और पास्ता के लिए::40 ग्राम साबुत गेहूँ का स्पैघेटी, आधा तोड़ा हुआ","चावल और पास्ता के लिए::2 छोटे चम्मच घी (9 ग्राम)","चावल और पास्ता के लिए::½ छोटा चम्मच मिश्रित सऊदी मसाला (बज़ार) और एक चुटकी हल्दी","चावल और पास्ता के लिए::⅔ छोटा चम्मच नमक (4 ग्राम)","सजाने और परोसने के लिए::20 ग्राम भुने बादाम","सजाने और परोसने के लिए::20 ग्राम किशमिश","सजाने और परोसने के लिए::2 उबले अंडे (100 ग्राम), चौथाई कटे हुए","सजाने और परोसने के लिए::1 टमाटर (100 ग्राम) और 1 खीरा (100 ग्राम), कटे हुए, और 1 नींबू (15 मिलीलीटर रस)"],
["मांस से दिखने वाली चर्बी हटाएँ, उसे 1.5 लीटर पानी, प्याज़, लहसुन, गाजर और साबुत मसालों के साथ बर्तन में रखें, झाग हटाते हुए उबाल आने दें, फिर 1½ घंटे धीमी आँच पर पकाएँ जब तक नरम न हो जाए।","चावल धोकर 30 मिनट भिगोएँ। मांस निकालें, स्टॉक छान लें और ऊपर से चर्बी हटा दें।","ओवन को 220 °C पर गरम करें। टमाटर पेस्ट को तेल और आधे केसर के साथ मिलाएँ, मांस पर लगाएँ और ट्रे में 15–20 मिनट भूनें जब तक भूरा न हो जाए।","400 मिलीलीटर स्टॉक को घी, मसाले, हल्दी और नमक के साथ उबालें, छाने हुए चावल डालें और तेज़ आँच पर स्टॉक सोखने तक पकाएँ, फिर ढककर धीमी आँच पर 20 मिनट पकाएँ और बाकी केसर ऊपर छिड़कें।","स्पैघेटी को बचे स्टॉक (या पानी) में नरम होने तक उबालें और छान लें।","बादाम को सूखी कड़ाही में हल्का सुनहरा होने तक भूनें।","चावल को परोसने की थाल में फैलाएँ, किनारों पर पास्ता और बीच में कटा मांस सजाएँ, ऊपर बादाम, किशमिश और उबले अंडे रखें, और टमाटर, खीरे और नींबू के साथ परोसें।"],
["क्या बदला गया: कम वसा वाली छँटी मेमने की जाँघ, प्रति व्यक्ति लगभग 150 ग्राम पके चावल और साबुत गेहूँ का पास्ता, बिना तेल के भुने बादाम, कम घी, और स्टॉक क्यूब की जगह घर का बना स्टॉक।","किडनी के लिए सुझाव: मांस, अंडे और बादाम में फॉस्फोरस होता है और किशमिश तथा टमाटर पेस्ट पोटैशियम बढ़ाते हैं; मांस 90 ग्राम तक रखें, किशमिश न डालें, और केवल अंडे की सफ़ेदी ले सकते हैं।","मधुमेह के लिए सुझाव: एक प्लेट में लगभग 56 ग्राम कार्बोहाइड्रेट होता है; सलाद से शुरुआत करें, और आधे चावल की जगह ब्राउन राइस या दलिया (बुलगुर) ले सकते हैं।","इनके लिए उपयुक्त: मधुमेह वाले लोग।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, फ़तफ़ात, विकिपीडिया (क़ोज़ी)"],[]),
(8861033,"हिजाज़ी मेमने का ज़िरबियान","ज़िरबियान अदन और यमन का चावल का व्यंजन है जो मक्का और जेद्दा में भी लंबे समय से बनता आया है: मांस और आलू को दही, प्याज़, लहसुन और मसालों में मैरिनेट करके पकाया जाता है, फिर आधे उबले चावल से ढककर केसर की सुगंध दी जाती है। इस नुस्खे में कम वसा वाली मेमने की जाँघ, कम वसा वाला दही, स्टॉक क्यूब और तैयार करी मसाले की जगह साबुत मसाले, सीमित नमक और बासमती चावल की मध्यम मात्रा है।","4","1 प्लेट (लगभग 450 ग्राम)",
["मांस और मैरिनेड::600 ग्राम कम वसा वाली मेमने की जाँघ, टुकड़ों में, दिखने वाली चर्बी हटाई हुई","मांस और मैरिनेड::300 ग्राम आलू (2 मध्यम), छिले और आधे कटे हुए","मांस और मैरिनेड::200 ग्राम कम वसा वाला दही","मांस और मैरिनेड::2 मध्यम प्याज़ (220 ग्राम): आधा प्याज़ मैरिनेड के लिए कद्दूकस किया हुआ, बाकी पतले कटे हुए","मांस और मैरिनेड::4 लहसुन की कलियाँ (15 ग्राम), कुटी हुई","मांस और मैरिनेड::10 ग्राम ताज़ा अदरक, कद्दूकस किया हुआ","मांस और मैरिनेड::1 बड़ा चम्मच सिरका (10 मिलीलीटर)","मांस और मैरिनेड::1 छोटा चम्मच पिसा धनिया + 1 छोटा चम्मच पिसा जीरा","मांस और मैरिनेड::½ छोटा चम्मच हल्दी + ½ छोटा चम्मच काली मिर्च","मांस और मैरिनेड::½ छोटा चम्मच पिसी इलायची + ½ छोटा चम्मच पिसी दालचीनी","मांस और मैरिनेड::2 बड़े चम्मच ऑलिव ऑयल (25 मिलीलीटर)","मांस और मैरिनेड::¾ छोटा चम्मच नमक (4 ग्राम)","चावल::200 ग्राम बासमती चावल (पकने पर लगभग 600 ग्राम)","चावल::3 इलायची + 3 लौंग + 1 दालचीनी की डंडी + 1 तेज पत्ता","चावल::एक चुटकी नमक (1 ग्राम)","चावल::एक चुटकी केसर, 2 बड़े चम्मच गुलाबजल या गुनगुने पानी में भिगोया हुआ"],
["आलू को छीलकर आधा काटें, 1 घंटा गरम पानी में भिगोएँ, फिर ताज़े पानी में 5 मिनट उबालें और छान लें (इससे पोटैशियम घटता है)।","दही को कद्दूकस किए प्याज़, लहसुन, अदरक, सिरके, पिसे मसालों और आधे नमक के साथ मिलाएँ, और मांस को कम से कम 1 घंटा उसमें मैरिनेट करें।","भारी बर्तन में ऑलिव ऑयल गरम करें और कटे प्याज़ को मध्यम आँच पर नरम और सुनहरा भूरा होने तक पकाएँ; सजाने के लिए आधा निकाल लें।","मांस को मैरिनेड से निकालकर बर्तन में डालें और 10 मिनट भूरा होने तक चलाएँ, फिर मैरिनेड, 250 मिलीलीटर गरम पानी और बचा नमक डालें।","ढककर 50–60 मिनट धीमी आँच पर पकाएँ जब तक मांस नरम न हो जाए, आख़िरी 20 मिनट आलू मांस के ऊपर रखें। थोड़ी गाढ़ी सॉस बाकी रहनी चाहिए।","इस बीच चावल धोकर 20 मिनट भिगोएँ, फिर इलायची, लौंग, दालचीनी, तेज पत्ते और चुटकी भर नमक वाले पानी में 6–7 मिनट उबालकर आधा पकाएँ और छान लें।","चावल को मांस और आलू पर फैलाएँ और भिगोया केसर तथा बचा भूरा प्याज़ ऊपर छिड़कें।","बर्तन को कसकर ढकें और बहुत धीमी आँच पर 15–20 मिनट रखें जब तक चावल पक न जाएँ।","परोसते समय परतों को हल्के से मिलाएँ और हरे सलाद या खीरे और कम वसा वाले दही के सलाद के साथ परोसें।"],
["क्या बदला गया: स्टॉक क्यूब और नमकीन तैयार करी मसाला नहीं हैं, पूरे बर्तन के लिए 5 ग्राम नमक, कम वसा वाला मांस, कम वसा वाला दही, प्याज़ तलने के लिए ढेर सारे तेल की जगह केवल 2 बड़े चम्मच तेल, और प्रति हिस्सा 150 ग्राम पके चावल।","किडनी के लिए सुझाव: आलू, मांस और दही पोटैशियम और फॉस्फोरस के स्रोत हैं; आलू को चरण 1 की तरह भिगोकर उबालें या उनकी जगह कद्दू या तोरी लें, और एक ही हिस्सा लें।","मधुमेह के लिए सुझाव: एक हिस्से में चावल और आलू से लगभग 66 ग्राम कार्बोहाइड्रेट होता है; आधे आलू की जगह तोरी या गाजर ले सकते हैं या कुछ ब्राउन राइस मिला सकते हैं, और सलाद से शुरुआत करें।","इनके लिए उपयुक्त: ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, अरबी विकिपीडिया (ज़ुर्बियान), सैयदाती किचन"],[]),
(8866678,"हिजाज़ी सब्ज़ी मुसक़्क़आ","हिजाज़ के घरों में बनने वाला मुसक़्क़आ: बैंगन, आलू और गाजर प्याज़ और मिर्च के साथ गाढ़ी टमाटर की सॉस में, जिसे चावल या रोटी के साथ परोसा जाता है। यहाँ सब्ज़ियाँ तलने की जगह थोड़े ऑलिव ऑयल में ओवन में भूनी गई हैं, और टमाटर पेस्ट बिना नमक वाला है।","4","1 प्लेट (लगभग 330 ग्राम)",
["2 मध्यम बैंगन, टुकड़ों में कटे हुए (500 ग्राम)","2 मध्यम आलू, छिले और टुकड़ों में कटे हुए (250 ग्राम)","2 गाजर, छोटे टुकड़ों में कटी हुई (150 ग्राम)","1½ बड़े चम्मच ऑलिव ऑयल (22.5 ग्राम)","1 बड़ा प्याज़, कटा हुआ (150 ग्राम)","2 हरी मिर्च, पतली कटी हुई (15 ग्राम)","3 लहसुन की कलियाँ, कुटी हुई (10 ग्राम)","3 टमाटर, कटे हुए (300 ग्राम)","1 बड़ा चम्मच बिना नमक वाला टमाटर पेस्ट (15 ग्राम)","½ छोटा चम्मच काली मिर्च, ½ छोटा चम्मच जीरा और ½ छोटा चम्मच पिसा धनिया","1 बड़ी चुटकी नमक (2.5 ग्राम)"],
["आलू के टुकड़ों को 30 मिनट गुनगुने पानी में भिगोएँ, फिर छानकर पोंछ लें।","ओवन को 220 °C पर गरम करें। बैंगन, आलू और गाजर को 1 बड़े चम्मच तेल के साथ मिलाएँ और बेकिंग पेपर लगी ट्रे पर फैलाएँ।","25–30 मिनट भूनें, एक बार पलटें, जब तक भूरे और नरम न हो जाएँ।","बर्तन में बाकी तेल गरम करें और प्याज़ व मिर्च को बिना भूरा किए नरम करें, फिर लहसुन डालें।","टमाटर, टमाटर पेस्ट, मसाले, नमक और 100 मिलीलीटर पानी डालें और 10 मिनट गाढ़ा होने तक पकाएँ।","भुनी सब्ज़ियाँ डालें, धीरे से चलाएँ, ढककर 10 मिनट पकाएँ ताकि सॉस सोख ली जाए। गरम या गुनगुना परोसें।"],
["क्या बदला गया: सब्ज़ियाँ डीप फ्राई करने की जगह एक चम्मच तेल में भूनी गई हैं, बिना नमक वाला टमाटर पेस्ट और थोड़ा नमक।","किडनी के लिए सुझाव: आलू, टमाटर और बैंगन में पोटैशियम होता है; आलू को छोटा काटें और भूनने से पहले बहुत सारे पानी में 10 मिनट उबालकर पानी फेंक दें, या उनकी जगह अधिक बैंगन और गाजर लें, और छोटी प्लेट ही लें।","मधुमेह के लिए सुझाव: एक प्लेट में आलू से लगभग 30 ग्राम कार्बोहाइड्रेट होता है; यदि चावल या रोटी के साथ परोसें तो चावल या रोटी आधी कर दें।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, शाकाहारी, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, सैयदाती किचन, मौज़ू3"],[]),
(8872488,"हिजाज़ी मंटू","मंटू कीमे और प्याज़ से भरे भाप में पकाए पकौड़े (डम्पलिंग) हैं; ये हिजाज़ में, ख़ासकर मक्का और जेद्दा में, बुख़ारा मूल का प्रसिद्ध व्यंजन हैं, जिन्हें दही की सॉस और तीखी टमाटर की सॉस के साथ परोसा जाता है। इस नुस्खे में आधा साबुत गेहूँ का आटा, कम वसा वाला मांस, कम वसा वाला दही और थोड़ा नमक है, और मंटू तले नहीं बल्कि भाप में पकाए जाते हैं।","4","दोनों सॉस के साथ 6 मंटू (लगभग 350 ग्राम)",
["आटे के लिए::100 ग्राम साबुत गेहूँ का आटा","आटे के लिए::100 ग्राम मैदा","आटे के लिए::1 अंडा (50 ग्राम)","आटे के लिए::1 चुटकी नमक (1 ग्राम)","आटे के लिए::लगभग 90 मिलीलीटर पानी","भरावन के लिए::500 ग्राम कम वसा वाला गोमांस का कीमा (90% कम वसा)","भरावन के लिए::2 मध्यम प्याज़ (200 ग्राम), कद्दूकस और निचोड़े हुए","भरावन के लिए::1 छोटा चम्मच जीरा, ½ छोटा चम्मच काली मिर्च, ¼ छोटा चम्मच लाल मिर्च पाउडर","भरावन के लिए::⅓ छोटा चम्मच नमक (2 ग्राम)","भरावन के लिए::स्टीमर पर लगाने के लिए 1 छोटा चम्मच ऑलिव ऑयल (4.5 ग्राम)","दही की सॉस के लिए::200 ग्राम कम वसा वाला दही","दही की सॉस के लिए::1 लहसुन की कली (4 ग्राम), कुटी हुई, और ½ छोटा चम्मच सूखा पुदीना","तीखी सॉस के लिए::2 टमाटर (200 ग्राम)","तीखी सॉस के लिए::1 हरी मिर्च (10 ग्राम) और 1 लहसुन की कली (4 ग्राम)","तीखी सॉस के लिए::1 बड़ा चम्मच नींबू का रस (15 मिलीलीटर) और 1 मुट्ठी ताज़ा धनिया (10 ग्राम)"],
["दोनों आटों को नमक और अंडे के साथ मिलाएँ, पानी थोड़ा-थोड़ा करके डालें और नरम, चिकना आटा गूँधें जो चिपके नहीं। ढककर 30 मिनट रखा रहने दें।","मांस को निचोड़े प्याज़, जीरे, काली मिर्च, लाल मिर्च और नमक के साथ अच्छी तरह मिलाएँ।","आटे को पतला बेलें और 24 चौकोर टुकड़ों (लगभग 8 सेमी) में काटें। हर एक के बीच में एक चम्मच भरावन रखें, चारों कोनों को ऊपर लाएँ और अच्छी तरह दबाकर बंद करें।","स्टीमर की ट्रे पर तेल लगाएँ, मंटू को आपस में जगह छोड़कर सजाएँ, उबलते पानी के ऊपर रखें, ढकें और 35–40 मिनट भाप में पकाएँ जब तक भरावन पक न जाए।","दही की सॉस के लिए: दही को लहसुन और पुदीने के साथ मिलाएँ।","तीखी सॉस के लिए: टमाटर, मिर्च, लहसुन, नींबू का रस और धनिया को ब्लेंडर में दरदरा पीस लें।","मंटू को गरम दोनों सॉस और ऊपर से जीरे व काली मिर्च के हल्के छिड़काव के साथ परोसें।"],
["क्या बदला गया: मंटू तले नहीं, भाप में पकाए गए हैं, आधा आटा साबुत गेहूँ का है, चर्बीदार मांस और घी की जगह 90% कम वसा वाला मांस है, दही कम वसा वाला है, और तीखी सॉस ताज़े टमाटर की है जिसमें नमक नहीं डाला गया।","किडनी के लिए सुझाव: मांस, दही और टमाटर से फॉस्फोरस और पोटैशियम बढ़ता है; 6 की जगह 4 मंटू खाएँ, दही की सॉस केवल 2 बड़े चम्मच लें, और तीखी सॉस में टमाटर की जगह भुनी लाल शिमला मिर्च ले सकते हैं।","मधुमेह के लिए सुझाव: एक हिस्से (6 मंटू) में लगभग 48 ग्राम कार्बोहाइड्रेट होता है; इसे बड़े हरे सलाद के साथ परोसें और अतिरिक्त चावल या रोटी न लें।","इनके लिए उपयुक्त: मधुमेह वाले लोग।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, लयालीना यम्मी, मौज़ू3"],[]),
(8874214,"क़सीमी फ़तीत","फ़तीत नज्द का पारंपरिक बिस्कुट है, जो अल-क़सीम में मशहूर है: साबुत गेहूँ के आटे की भुरभुरी गोल कुकीज़, जिनमें इलायची, अदरक और केसर होता है, जिन्हें सेंका जाता है और शहद, दालचीनी व काले नींबू की चाशनी के साथ परोसा जाता है। इस नुस्खे में चीनी सामान्य से एक तिहाई से भी कम, तेल आधे से भी कम, और स्किम्ड मिल्क पाउडर है।","16","1 गोल कुकी (लगभग 35 ग्राम) और 1 छोटा चम्मच चाशनी",
["आटे के लिए::300 ग्राम साबुत गेहूँ का आटा","आटे के लिए::2 बड़े चम्मच स्किम्ड मिल्क पाउडर (15 ग्राम)","आटे के लिए::1 अंडा (50 ग्राम)","आटे के लिए::1 छोटा चम्मच बेकिंग पाउडर (4 ग्राम)","आटे के लिए::60 ग्राम चीनी (5 बड़े चम्मच)","आटे के लिए::60 मिलीलीटर हल्का ऑलिव ऑयल (55 ग्राम)","आटे के लिए::1 चुटकी नमक (1 ग्राम)","आटे के लिए::½ छोटा चम्मच पिसी इलायची","आटे के लिए::½ छोटा चम्मच पिसी अदरक","आटे के लिए::1 चुटकी केसर 1 बड़े चम्मच पानी में भिगोया हुआ (या ¼ छोटा चम्मच हल्दी)","आटे के लिए::लगभग 150 मिलीलीटर पानी","चाशनी के लिए::2 बड़े चम्मच शहद (40 ग्राम)","चाशनी के लिए::60 मिलीलीटर पानी","चाशनी के लिए::1 छोटा चम्मच पिसी दालचीनी","चाशनी के लिए::½ छोटा चम्मच पिसी इलायची","चाशनी के लिए::½ छोटा चम्मच पिसा काला नींबू (लूमी)"],
["ओवन को ऊपर और नीचे की गर्मी के साथ 190°C पर गरम करें और दो ट्रे पर बेकिंग पेपर बिछाएँ।","अंडे को चीनी, तेल, भिगोए केसर, इलायची, अदरक और नमक के साथ फेंटें।","आटे को मिल्क पाउडर और बेकिंग पाउडर के साथ मिलाएँ, इसे अंडे के मिश्रण में पानी के साथ थोड़ा-थोड़ा करके डालें और सख़्त आटा गूँधें जिसे आकार देना आसान हो और जो चिपके नहीं।","आटे के 16 गोले बनाएँ और हर एक को लगभग 1 सेमी मोटी गोल कुकी में चपटा करें। नक़्श बनाने के लिए इसे लकड़ी के फ़तीत साँचे से, या टोकरी या छन्नी से दबाएँ।","15–20 मिनट सेंकें जब तक किनारे और तली सुनहरे न हो जाएँ, फिर जाली पर ठंडा करें।","चाशनी के लिए: पानी को शहद, दालचीनी, इलायची और काले नींबू के साथ 2 मिनट उबालें जब तक थोड़ा गाढ़ा न हो जाए, फिर छान लें।","हर कुकी पर 1 छोटा चम्मच चाशनी डालकर या डुबोने के लिए अलग से परोसें।"],
["क्या बदला गया: लगभग 200 ग्राम की जगह 60 ग्राम चीनी, लगभग 180 मिलीलीटर की जगह 60 मिलीलीटर तेल, स्किम्ड मिल्क पाउडर, और प्रति कुकी थोड़ी मात्रा में हल्की शहद की चाशनी।","किडनी के लिए सुझाव: साबुत गेहूँ का आटा, मिल्क पाउडर और बेकिंग पाउडर में फॉस्फोरस होता है; एक ही कुकी लें, और आप कम सोडियम वाला बेकिंग पाउडर और आधा मैदा इस्तेमाल कर सकते हैं।","मधुमेह के लिए सुझाव: एक कुकी में 6 ग्राम मिलाई गई चीनी सहित लगभग 20 ग्राम कार्बोहाइड्रेट होता है; बिना चीनी की अरबी कॉफ़ी के साथ एक ही कुकी लें और हो सके तो चाशनी छोड़ दें।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, किडनी रोग (डायलिसिस पर नहीं), डायलिसिस पर रहने वाले लोग, शाकाहारी।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, अरबी विकिपीडिया (फ़तीत), ख़लीज किचन (क़सीम की क्लीचा)"],[]),
(8879817,"नज्दी लाल हरीस","नज्दी हरीस साबुत गेहूँ है जिसे मांस, टमाटर और मसालों के साथ कई घंटे धीमी आँच पर पकाया जाता है, फिर घोंटकर चिकना किया जाता है और ऊपर प्याज़ की कशना डाली जाती है; यह नज्द और हाइल में लोकप्रिय है। इस नुस्खे में कम वसा वाला मांस, एक चम्मच तेल और कशना में ढेर सारे घी की जगह थोड़ा घी, बिना नमक वाला टमाटर पेस्ट और थोड़ा नमक है।","4","1 कटोरा (लगभग 400 ग्राम)",
["हरीस के लिए::240 ग्राम हरीस गेहूँ (छिलका उतरा साबुत गेहूँ), धोया हुआ और 2 घंटे भिगोया हुआ","हरीस के लिए::600 ग्राम कम वसा वाला बिना हड्डी का वील या जवान ऊँट का मांस, दिखने वाली चर्बी हटाई हुई, टुकड़ों में","हरीस के लिए::1 बड़ा चम्मच ऑलिव ऑयल (13.5 ग्राम)","हरीस के लिए::1 बड़ा प्याज़, बारीक कटा हुआ (150 ग्राम)","हरीस के लिए::2 बड़े टमाटर, कद्दूकस किए हुए (250 ग्राम)","हरीस के लिए::2 बड़े चम्मच बिना नमक वाला टमाटर पेस्ट (30 ग्राम)","हरीस के लिए::1 छोटा चम्मच मिश्रित सऊदी मसाला (बज़ार), 1 छोटा चम्मच हल्दी, ½ छोटा चम्मच पिसी लाल मिर्च, ½ छोटा चम्मच इलायची","हरीस के लिए::लगभग 2.5 लीटर उबलता पानी","हरीस के लिए::¾ छोटा चम्मच नमक (4.5 ग्राम)","कशना की परत के लिए::2 छोटे चम्मच घी (9 ग्राम)","कशना की परत के लिए::1 मध्यम प्याज़, पतला कटा हुआ (100 ग्राम)","कशना की परत के लिए::1 हरी मिर्च, कटी हुई (15 ग्राम)","कशना की परत के लिए::½ छोटा चम्मच पिसा सूखा नींबू (लूमी)"],
["बड़े भारी बर्तन में तेल गरम करें और प्याज़ को नरम होने तक पकाएँ, फिर मांस और मसाले डालकर 8–10 मिनट भूरा करें।","कद्दूकस किया टमाटर और टमाटर पेस्ट डालकर 5 मिनट गाढ़ा होने तक चलाएँ।","छना हुआ गेहूँ और उबलता पानी डालें, उबाल आने दें, फिर आँच बहुत धीमी करके ढककर 3½–4 घंटे पकाएँ, बीच-बीच में चलाते रहें और ज़रूरत पर उबलता पानी डालें (या प्रेशर कुकर में 1½ घंटे)।","आख़िरी घंटे में नमक डालें, फिर गरम रहते ही हरीस को लकड़ी की मथनी या हैंड ब्लेंडर से घोंटें जब तक मांस बिखरकर गेहूँ में मिल न जाए।","कशना के लिए: छोटी कड़ाही में घी गरम करें और प्याज़ को सुनहरा होने तक तलें, फिर मिर्च और सूखा नींबू डालकर 1 मिनट पकाएँ।","हरीस को परोसने के डिश में फैलाएँ, ऊपर कशना डालें और हरे सलाद के साथ गरम परोसें।"],
["क्या बदला गया: कम वसा वाला मांस, ढेर सारे मक्खन और घी की जगह पूरे बर्तन के लिए 1 बड़ा चम्मच तेल और 2 छोटे चम्मच घी, पूरे डिब्बे की टमाटर सॉस की जगह बिना नमक वाला टमाटर पेस्ट, और कम नमक।","किडनी के लिए सुझाव: साबुत गेहूँ और मांस में फॉस्फोरस अधिक होता है, और टमाटर तथा टमाटर पेस्ट में पोटैशियम; टमाटर पेस्ट आधा करें, एक ही हिस्सा (लगभग 100 ग्राम पका मांस) लें और साबुत अनाज के बारे में अपने आहार विशेषज्ञ से पूछें।","मधुमेह के लिए सुझाव: एक कटोरे में फाइबर से भरपूर साबुत अनाज से लगभग 53 ग्राम कार्बोहाइड्रेट होता है; इसे सलाद के साथ खाएँ और ऊपर चीनी न डालें।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग।","संदर्भ: एनसाइक्लोपीडिया कुकिंग (encyclopediacooking.com), सैयदाती किचन (मांस और प्याज़ वाली हरीस), सऊदीपीडिया (हाइल के लोकप्रिय व्यंजन)"],[]),
(8882310,"चिकन के साथ बुख़ारी चावल","बुख़ारी चावल मक्का, मदीना और जेद्दा का मशहूर हिजाज़ी व्यंजन है जिसकी जड़ें बुख़ारा में हैं: बासमती चावल को मसालेदार चिकन शोरबे में गाजर के साथ पकाया जाता है, ऊपर गाजर और किशमिश डाली जाती हैं और ओवन में भूने चिकन के साथ परोसा जाता है। इस नुस्खे में बिना त्वचा का चिकन, थोड़ा ऑलिव ऑयल और बिना नमक वाला टमाटर पेस्ट है, स्टॉक क्यूब या सोया सॉस नहीं हैं।","4","1 प्लेट (लगभग 420 ग्राम)",
["चिकन के लिए::300 ग्राम बिना त्वचा की चिकन ब्रेस्ट, 2 टुकड़ों में","चिकन के लिए::300 ग्राम बिना त्वचा और बिना हड्डी की चिकन जाँघ","चिकन के लिए::1 मध्यम प्याज़ (150 ग्राम), बारीक कटा हुआ","चिकन के लिए::3 लहसुन की कलियाँ (10 ग्राम), कुटी हुई","चिकन के लिए::2 टमाटर (200 ग्राम), कटे हुए","चिकन के लिए::1 बड़ा चम्मच बिना नमक वाला टमाटर पेस्ट (15 ग्राम)","चिकन के लिए::½ संतरे का छिलका (5 ग्राम)","चिकन के लिए::साबुत मसाले: 5 इलायची, 4 लौंग, 1 दालचीनी की डंडी, 1 तेज पत्ता, ½ छोटा चम्मच काली मिर्च के दाने","चिकन के लिए::पिसा बुख़ारी मसाला: 1 छोटा चम्मच जीरा, ½ छोटा चम्मच धनिया, ½ छोटा चम्मच काला नींबू, ¼ छोटा चम्मच इलायची","चिकन के लिए::भूरा करने के लिए ¼ छोटा चम्मच हल्दी","चावल के लिए::200 ग्राम बासमती चावल, धोए हुए और 30 मिनट भिगोए हुए","चावल के लिए::¾ छोटा चम्मच नमक (5 ग्राम)","चावल और ऊपर की परत के लिए::2 बड़ी गाजर (250 ग्राम), पतली फाँकों में कटी हुई","चावल और ऊपर की परत के लिए::30 ग्राम किशमिश","चावल और ऊपर की परत के लिए::2 बड़े चम्मच ऑलिव ऑयल (27 ग्राम)"],
["बर्तन में 1 बड़ा चम्मच तेल गरम करें और प्याज़ को साबुत मसालों के साथ नरम और हल्का सुनहरा होने तक पकाएँ, फिर लहसुन और संतरे का छिलका डालकर चलाएँ।","चिकन डालकर रंग बदलने तक पलटें, फिर टमाटर, टमाटर पेस्ट और एक चौथाई गाजर डालकर 2 मिनट चलाएँ।","800 मिलीलीटर गरम पानी डालें, उबाल आने दें, फिर 25–30 मिनट धीमी आँच पर पकाएँ, आख़िरी 5 मिनट में पिसा मसाला डालें।","चिकन को ओवन ट्रे पर निकालें, शोरबा छानें और 400 मिलीलीटर नाप लें।","शोरबे को नमक के साथ बर्तन में वापस डालें; उबाल आने पर छाने हुए चावल और बची गाजर का आधा हिस्सा डालें। तेज़ आँच पर तरल सोखने तक पकाएँ, फिर कसकर ढकें और बहुत धीमी आँच पर 20 मिनट रखें।","इस बीच 3 बड़े चम्मच शोरबा, हल्दी और 1 छोटा चम्मच तेल मिलाएँ, चिकन पर लगाएँ और 220°C पर (ऊपर की गर्मी से) 10–15 मिनट ग्रिल करें, एक-दो बार लगाते हुए, जब तक भूरा न हो जाए।","कड़ाही में बचा तेल गरम करें और बची गाजर को नरम होने तक चलाएँ, फिर एक मिनट के लिए किशमिश डालें।","चावल को थाल में निकालें, किनारे पर गाजर और किशमिश बिखेरें, बीच में चिकन रखें और टमाटर-खीरे के सलाद के साथ परोसें।"],
["क्या बदला गया: त्वचा वाले पूरे मुर्गे की जगह बिना त्वचा का चिकन, केवल 2 बड़े चम्मच तेल, बिना नमक वाला टमाटर पेस्ट, गाजर पर सीज़निंग पाउडर, सोया सॉस या चीनी नहीं, और अतिरिक्त नमक की जगह स्वाद के लिए संतरे का छिलका और काला नींबू।","किडनी के लिए सुझाव: टमाटर, टमाटर पेस्ट, किशमिश और गाजर पोटैशियम बढ़ाते हैं; एक टमाटर लें, किशमिश घटाकर 15 ग्राम करें, और प्रति हिस्सा लगभग 90 ग्राम पका चिकन रखें।","मधुमेह के लिए सुझाव: एक हिस्से में लगभग 59 ग्राम कार्बोहाइड्रेट होता है; 150 ग्राम पके चावल तक ही रखें, आधे चावल ब्राउन राइस बना सकते हैं, और बड़े सलाद के साथ परोसें।","इनके लिए उपयुक्त: मधुमेह वाले लोग, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, हिया पत्रिका, सैयदाती किचन"],[]),
(8888089,"चिकन के साथ क़तीफ़ी महमूस","महमूस क़तीफ़, अल-अहसा और बहरीन का चावल का व्यंजन है, जो बहुत सारे प्याज़ को लगभग काला होने तक भूनने और सूखे काले नींबू से गहरे भूरे रंग का होता है, और चिकन, मांस या मछली के साथ पकाया जाता है। यहाँ प्याज़ को पानी के छींटों के साथ धीरे-धीरे कैरेमलाइज़ किया गया है और तेल बहुत कम है, बिना त्वचा का चिकन, थोड़ा नमक और स्टॉक क्यूब नहीं हैं।","4","1 प्लेट (लगभग 420 ग्राम)",
["600 ग्राम बिना त्वचा का चिकन (जाँघ और ब्रेस्ट), 8 टुकड़ों में कटा हुआ","200 ग्राम बासमती चावल, धोए हुए और 30 मिनट भिगोए हुए (लगभग 250 मिलीलीटर)","5 मध्यम प्याज़, पतले कटे हुए (500 ग्राम)","2 बड़े चम्मच ऑलिव ऑयल (28 ग्राम)","5 लहसुन की कलियाँ, कुटी हुई (15 ग्राम)","3 छेदे हुए सूखे काले नींबू (लूमी)","साबुत मसाले: 1 दालचीनी की डंडी, 5 इलायची, 4 लौंग, 2 तेज पत्ते","2 छोटे चम्मच बिना नमक का मिश्रित मसाला (बज़ार), ¾ छोटा चम्मच हल्दी, ½ छोटा चम्मच काली मिर्च","¾ छोटा चम्मच नमक (4.5 ग्राम)","लगभग 900 मिलीलीटर गरम पानी"],
["प्याज़ को चौड़े भारी बर्तन में मध्यम आँच पर पानी के एक छींटे के साथ रखें और नरम होने व पानी उड़ने तक चलाएँ।","तेल डालें और 25–30 मिनट चलाते रहें, जब भी चिपकने लगे तो पानी का छींटा डालें, जब तक प्याज़ बहुत गहरे भूरे न हो जाएँ पर जलें नहीं।","साबुत और पिसे मसाले और लहसुन डालकर 2 मिनट चलाएँ, फिर पानी का छींटा डालकर 3 मिनट ढक दें।","चिकन डालें और 10 मिनट पलटते रहें जब तक उस पर प्याज़ का भूरा रंग न चढ़ जाए।","गरम पानी, लूमी और नमक डालें, ढक दें और 30 मिनट धीमी आँच पर पकाएँ जब तक चिकन पक न जाए।","चिकन को ट्रे पर निकालें और बिना अतिरिक्त चिकनाई के 220 °C पर पहले से गरम ओवन में 10 मिनट भूरा करें।","शोरबा नापें: लगभग 375 मिलीलीटर चाहिए। छाने हुए चावल डालें और बिना ढके और बिना चलाए तब तक उबालें जब तक शोरबा सोख न लिया जाए।","आँच सबसे धीमी कर दें, ढकें और 20 मिनट पकाएँ जब तक चावल पक न जाएँ।","चावल को थाल में निकालें, ऊपर चिकन रखें और हरे सलाद और खीरे के साथ परोसें।"],
["क्या बदला गया: प्याज़ तेल में डुबोने की जगह पानी के छींटों के साथ 2 बड़े चम्मच तेल में भूने गए हैं, चिकन बिना त्वचा का है और ओवन में भूरा किया गया है, स्टॉक क्यूब नहीं हैं, और प्रति व्यक्ति लगभग 150 ग्राम पके चावल हैं।","किडनी के लिए सुझाव: चिकन में फॉस्फोरस और पोटैशियम अधिक होता है; एक ही प्लेट (लगभग 100 ग्राम पका चिकन) लें। इस व्यंजन में टमाटर या आलू नहीं हैं, इसलिए यह कई चावल के व्यंजनों से कम पोटैशियम वाला है।","मधुमेह के लिए सुझाव: एक प्लेट में लगभग 54 ग्राम कार्बोहाइड्रेट होता है; बड़े सलाद के साथ परोसें, और एक चौथाई ब्राउन राइस मिला सकते हैं।","इनके लिए उपयुक्त: मधुमेह वाले लोग, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग (मौसूअत अल तबख), विकिपीडिया, कुकिनस्टा"],[]),
(8892072,"शक्शूका","सऊदी शक्शूका घर के नाश्ते का आम व्यंजन है: प्याज़, लहसुन, टमाटर और हरी मिर्च को जीरे के साथ गाढ़ी सॉस में पकाया जाता है, फिर अंडे डालकर जमने तक चलाए जाते हैं और इसे रोटी के साथ खाया जाता है। इस नुस्खे में थोड़ा ऑलिव ऑयल, कम नमक, साबुत अंडों की जगह कुछ अंडे की सफ़ेदी और अधिक सब्ज़ियाँ हैं।","4","1 प्लेट (लगभग 250 ग्राम), रोटी के बिना",
["4 साबुत अंडे (200 ग्राम) और 2 अंडे की सफ़ेदी (66 ग्राम)","2 मध्यम प्याज़, कटे हुए (220 ग्राम)","3 लहसुन की कलियाँ, कटी हुई (10 ग्राम)","3 मध्यम टमाटर, कटे हुए (360 ग्राम)","1 बड़ा चम्मच बिना नमक वाला टमाटर पेस्ट (15 ग्राम)","2 हरी मिर्च (20 ग्राम) और 1 छोटी हरी शिमला मिर्च (100 ग्राम), कटी हुई","1 बड़ा चम्मच ऑलिव ऑयल (13.5 ग्राम)","½ छोटा चम्मच जीरा, ½ छोटा चम्मच बज़ार, एक चुटकी काली मिर्च","1 बड़ी चुटकी नमक (2.5 ग्राम)","10 ग्राम ताज़ा धनिया, कटा हुआ"],
["चौड़ी कड़ाही में ऑलिव ऑयल गरम करें और प्याज़ को नरम होने तक पकाएँ, फिर लहसुन, मिर्च और शिमला मिर्च डालकर 2 मिनट चलाएँ।","जीरा और बज़ार मिलाएँ, फिर टमाटर, टमाटर पेस्ट और 50 मिलीलीटर पानी डालकर 8–10 मिनट ढक दें जब तक सॉस गाढ़ी न हो जाए।","साबुत अंडों को अंडे की सफ़ेदी, नमक और काली मिर्च के साथ फेंटें और सॉस पर डालें।","धीमी आँच पर बीच-बीच में धीरे से चलाएँ जब तक अंडे आपकी पसंद के अनुसार जम न जाएँ, फिर धनिया छिड़कें और साबुत गेहूँ की रोटी के साथ गरम परोसें।"],
["क्या बदला गया: पूरी कड़ाही के लिए 1 बड़ा चम्मच ऑलिव ऑयल, कम नमक, कोलेस्ट्रॉल घटाने के लिए 2 अंडों की जगह सफ़ेदी, और अधिक सब्ज़ियाँ।","किडनी के लिए सुझाव: टमाटर और टमाटर पेस्ट में पोटैशियम अधिक होता है और अंडे की ज़र्दी में फॉस्फोरस; आप टमाटर घटाकर 2 कर सकते हैं और शिमला मिर्च अधिक तथा अंडे की सफ़ेदी अधिक ले सकते हैं।","मधुमेह के लिए सुझाव: शक्शूका में कार्बोहाइड्रेट कम और प्रोटीन अधिक होता है; कार्बोहाइड्रेट रोटी से आता है, इसलिए आधी साबुत गेहूँ की रोटी लें।","इनके लिए उपयुक्त: मधुमेह वाले लोग, शाकाहारी, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, सैयदाती, लयालीना यम्मी"],[]),
]
P(5,R)
